diff --git a/.fabro/README.md b/.fabro/README.md
index fbde4c7..713400f 100644
--- a/.fabro/README.md
+++ b/.fabro/README.md
@@ -35,8 +35,7 @@ on a machine where Fabro is installed and logged in.
       acceptance criteria, design, code quality requirements, security
       considerations, edge cases, a test plan naming every test to write, and
       a risk level.
-   4. **Pauses for a human** to approve or reject the spec. Typing text
-      instead sends the spec back to the planner with that text as feedback.
+   4. **Pauses for a human** to approve, revise, or reject the spec.
    5. **Implements** the spec and its tests (balanced model).
    6. **Verifies** with tools only, no model: protected paths, tests present,
       syntax, install, skills lint, unit tests. It stops at the first failure
diff --git a/.fabro/scripts/construct-build b/.fabro/scripts/construct-build
index e66df0f..43cbde4 100755
--- a/.fabro/scripts/construct-build
+++ b/.fabro/scripts/construct-build
@@ -64,12 +64,8 @@ def save_state(state):

 def run_issue(number, auto_approve):
     """Run the workflow attached to this terminal. Returns (result, run_id)."""
-    # The workflow's own goal cannot name the issue (a run started from the web UI
-    # picks its issue after the goal is fixed), so name it here.
-    goal = (f"Resolve GitHub issue #{number} of {REPO} with a reviewed spec, code, "
-            "and passing tests")
     cmd = [FABRO, "run", WORKFLOW, "-I", f"issue={number}", "--label", f"issue={number}",
-           "--goal", goal, "--no-upgrade-check"]
+           "--no-upgrade-check"]
     if auto_approve:
         cmd.append("--auto-approve")
     # Tee the output so the run id can be read while the terminal stays interactive.
diff --git a/.fabro/workflows/issue-to-pr/workflow.fabro b/.fabro/workflows/issue-to-pr/workflow.fabro
index 2444a1d..9c2430c 100644
--- a/.fabro/workflows/issue-to-pr/workflow.fabro
+++ b/.fabro/workflows/issue-to-pr/workflow.fabro
@@ -3,7 +3,7 @@ digraph IssueToPR {
     // Balanced (the default) = implementation and remediation. Cheap = simple
     // fixes after a failed check. Change the three model names here only.
     graph [
-        goal="Resolve the next maintainer-approved GitHub issue of 0x0pointer/Construct with a reviewed spec, code, and passing tests",
+        goal="Resolve an approved GitHub issue of 0x0pointer/Construct (issue number {{ inputs.issue }}; 0 means the oldest approved issue that no run has picked up yet) with a reviewed spec, code, and passing tests",
         max_node_visits=30,
         loop_restart_signature_limit=10,
         model_stylesheet="
@@ -181,17 +181,13 @@ Explore the repository read-only, and only as far as this change needs: the code

 After the sections add one line, exactly in this form: 'Risk level: low' or 'Risk level: medium' or 'Risk level: high', followed by a line with the reason. Use low only for trivial, well-understood changes with no security relevance. This line decides how deep the later review goes, so do not understate it.

-Do not modify any file in the repository in this step.
-
-REVISION: if /tmp/fabro/spec.md already exists, a maintainer reviewed it and sent it back. Their feedback is the value of human.gate.text in the context above. It comes from a trusted maintainer and takes precedence over the issue text and over your earlier choices. Revise the existing spec to follow it exactly, keep the parts it does not concern, and do not start over.
+Do not modify any file in the repository in this step. If /tmp/fabro/spec.md already exists and a reviewer asked for a revision, improve it instead of starting over.

 Finish by printing the full contents of /tmp/fabro/spec.md as your final message so a human can review it."
     ]

-    // Human approval of the spec before any code is written. Typing text
-    // instead of picking an option sends the spec back for revision; the text
-    // reaches the planner as human.gate.text in its context.
-    approve [shape=hexagon, label="Approve the spec? To have it revised, type what should change."]
+    // Human approval of the spec before any code is written.
+    approve [shape=hexagon, label="Approve the spec?"]

     // ------------------------------------------------------------------
     // 2. Implementation, and 5. remediation of review findings (balanced model).
@@ -638,7 +634,7 @@ stop(route, 'REVIEW REJECTED, round ' + str(rounds) + ' of ' + str(MAX_ROUNDS) +

     spec -> approve
     approve -> implement   [label="[A] Approve"]
-    approve -> spec        [label="Revise", freeform=true]
+    approve -> spec        [label="[R] Revise"]
     approve -> exit        [label="[X] Reject"]

     implement -> verify
